/**
 * Putting a file into Notion.
 *
 * Grant asked the team to *"grab the various files generated by the notebook
 * such as audio snippets, etc and upload them to Notion"*, and the Chief of
 * Staff said she could not. She was right at the time and for two reasons, only
 * one of which was ours: nothing here implemented uploading, and the API
 * version the client was pinned to — `2022-06-28` — has no upload endpoint at
 * all. There was nothing to call.
 *
 * `2026-03-11` has one. Verified end to end against the live workspace before
 * this file was written: create, send, attach to a page as a file block, read
 * the block back, trash the page. Five calls, five 200s.
 *
 * ## The shape
 *
 *     POST /v1/file_uploads            -> { id, upload_url, complete_url, status }
 *     POST <upload_url>                 multipart/form-data, field "file"
 *     POST <complete_url>               multi-part only
 *     then reference it as { type: 'file_upload', file_upload: { id } }
 *
 * The id is what gets attached, and it is attachable to a media block, an
 * embed, a database file property, a page icon or a cover.
 *
 * ## Why the checks happen before the first call
 *
 * Grant: *"detecting unsupported files or size limits; reporting actionable
 * failures rather than silently falling back to text references."* An upload
 * that fails on the third of three calls has already spent two round trips and
 * produced a Notion error string that means nothing to him. Size and type are
 * knowable from the bytes in hand, so they are decided here, in a sentence that
 * says what to do.
 *
 * The workspace limit is the one that cannot be known locally: free workspaces
 * cap a single file at 5 MiB and paid ones at 5 GiB, and the API does not
 * publish which this is. So that failure is caught and translated rather than
 * predicted.
 */

import type { NotionClient } from './api.ts'

/** Notion's threshold between a single request and a multi-part upload. */
export const SINGLE_PART_LIMIT = 20 * 1024 * 1024
/** Notion's part size for multi-part uploads. */
export const PART_SIZE = 10 * 1024 * 1024
/** Notion's cap on a filename, in bytes including the extension. */
export const MAX_FILENAME_BYTES = 900

/**
 * What Notion accepts, by extension.
 *
 * Kept as an explicit table rather than "anything with a MIME type", because
 * the failure mode of guessing is an upload that Notion rejects after the bytes
 * have been sent. Audio and video matter most here — they are what a notebook
 * generates and what Grant asked for by name.
 */
const ACCEPTED: Readonly<Record<string, string>> = {
  // audio
  aac: 'audio/aac',
  mid: 'audio/midi',
  mp3: 'audio/mpeg',
  m4a: 'audio/mp4',
  ogg: 'audio/ogg',
  wav: 'audio/wav',
  wma: 'audio/x-ms-wma',
  // documents
  doc: 'application/msword',
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  json: 'application/json',
  md: 'text/markdown',
  pdf: 'application/pdf',
  ppt: 'application/vnd.ms-powerpoint',
  pptx: 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  txt: 'text/plain',
  xls: 'application/vnd.ms-excel',
  xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  csv: 'text/csv',
  // images
  gif: 'image/gif',
  heic: 'image/heic',
  jpeg: 'image/jpeg',
  jpg: 'image/jpeg',
  png: 'image/png',
  svg: 'image/svg+xml',
  webp: 'image/webp',
  // video
  amv: 'video/x-amv',
  avi: 'video/x-msvideo',
  mov: 'video/quicktime',
  mp4: 'video/mp4',
  mpeg: 'video/mpeg',
  webm: 'video/webm',
  wmv: 'video/x-ms-wmv',
}

export class NotionFileError extends Error {
  constructor(
    readonly reason: 'unsupported_type' | 'name_too_long' | 'too_large_for_workspace' | 'failed',
    message: string,
  ) {
    super(message)
    this.name = 'NotionFileError'
  }
}

/** The MIME type Notion will accept for a filename, or null if it will not. */
export const contentTypeFor = (filename: string): string | null => {
  const dot = filename.lastIndexOf('.')
  if (dot === -1) return null
  return ACCEPTED[filename.slice(dot + 1).toLowerCase()] ?? null
}

export interface Uploaded {
  readonly id: string
  readonly filename: string
  readonly bytes: number
  readonly parts: number
}

/**
 * Upload bytes and return the id to attach them by.
 *
 * Chooses single or multi-part from the size, because the caller should not
 * have to know where Notion's threshold is — and because getting it wrong is
 * not a graceful degradation, it is a rejection.
 */
export async function uploadFile(
  client: NotionClient,
  filename: string,
  bytes: Uint8Array,
  contentType?: string,
): Promise<Uploaded> {
  const type = contentType ?? contentTypeFor(filename)
  if (type === null) {
    throw new NotionFileError(
      'unsupported_type',
      `Notion does not accept "${filename}". It takes audio, video, images and ` +
        'documents — pdf, docx, mp3, mp4, png and the like. Convert it or link to it instead.',
    )
  }
  if (new TextEncoder().encode(filename).length > MAX_FILENAME_BYTES) {
    throw new NotionFileError(
      'name_too_long',
      `That filename is over ${String(MAX_FILENAME_BYTES)} bytes, which Notion refuses. Shorten it.`,
    )
  }

  const parts = bytes.length <= SINGLE_PART_LIMIT ? 1 : Math.ceil(bytes.length / PART_SIZE)

  const created = (await client.call('/file_uploads', {
    method: 'POST',
    body:
      parts === 1
        ? { mode: 'single_part', filename, content_type: type }
        : { mode: 'multi_part', filename, content_type: type, number_of_parts: parts },
  })) as { id?: string; upload_url?: string; complete_url?: string }

  const id = String(created.id ?? '')
  const uploadUrl = String(created.upload_url ?? '')
  if (id === '' || uploadUrl === '') {
    throw new NotionFileError('failed', 'Notion did not return an upload to send the file to.')
  }

  if (parts === 1) {
    await send(client, uploadUrl, filename, bytes, type)
  } else {
    for (let part = 1; part <= parts; part += 1) {
      const slice = bytes.slice((part - 1) * PART_SIZE, part * PART_SIZE)
      await send(client, uploadUrl, filename, slice, type, part)
    }
    await client.call(`/file_uploads/${id}/complete`, { method: 'POST', body: {} })
  }

  return { id, filename, bytes: bytes.length, parts }
}

/**
 * One request of bytes.
 *
 * Not through `client.call`: this is `multipart/form-data` rather than JSON and
 * it goes to a URL Notion hands back rather than to a path. It still carries
 * the same auth and version headers, and the same failures have to be
 * translated — so it lives here beside the thing that calls it rather than
 * distorting the JSON client to accommodate one shape.
 */
async function send(
  client: NotionClient,
  url: string,
  filename: string,
  bytes: Uint8Array,
  type: string,
  part?: number,
): Promise<void> {
  const form = new FormData()
  // `BlobPart` is not in this project's tsconfig lib. A Uint8Array is a legal
  // one at runtime, and the ArrayBuffer under it satisfies the narrower type
  // the lib does know about — `slice()` so a view into a larger buffer does not
  // send the whole thing.
  const buffer = bytes.buffer.slice(
    bytes.byteOffset,
    bytes.byteOffset + bytes.byteLength,
  ) as ArrayBuffer
  form.append('file', new Blob([buffer], { type }), filename)
  if (part !== undefined) form.append('part_number', String(part))

  const response = await fetch(url, {
    method: 'POST',
    headers: client.uploadHeaders(),
    body: form,
  })
  if (response.ok) return

  const detail = await response.text()
  // The one limit that cannot be checked locally: a free workspace caps a file
  // at 5 MiB and a paid one at 5 GiB, and nothing in the API says which this
  // is. Translated rather than predicted.
  if (/size|too large|limit/i.test(detail)) {
    throw new NotionFileError(
      'too_large_for_workspace',
      `Notion refused "${filename}" (${String(Math.round(bytes.length / 1024))}KB) as too large. ` +
        'A free workspace caps a single file at 5 MiB; a paid one at 5 GiB.',
    )
  }
  throw new NotionFileError(
    'failed',
    `Notion refused the upload of "${filename}": ${detail.slice(0, 180)}`,
  )
}

/**
 * A block that shows an uploaded file, of the right kind for what it is.
 *
 * Notion has distinct block types for audio, video, images and PDFs, and each
 * renders as the thing it is — an audio block gets a player, a `file` block
 * gets a download link. An audio overview delivered as a download link is
 * technically attached and practically useless, which is the difference §16
 * cares about.
 */
export function fileBlock(
  upload: Uploaded,
  caption?: string,
): { object: 'block'; type: string; [key: string]: unknown } {
  const type = contentTypeFor(upload.filename) ?? ''
  const kind = type.startsWith('audio/')
    ? 'audio'
    : type.startsWith('video/')
      ? 'video'
      : type.startsWith('image/')
        ? 'image'
        : type === 'application/pdf'
          ? 'pdf'
          : 'file'
  return {
    object: 'block',
    type: kind,
    [kind]: {
      type: 'file_upload',
      file_upload: { id: upload.id },
      caption: caption === undefined ? [] : [{ type: 'text', text: { content: caption } }],
      ...(kind === 'file' ? { name: upload.filename } : {}),
    },
  }
}

/** The same upload, as the value of a database file property. */
export const fileProperty = (uploads: readonly Uploaded[]): { files: unknown[] } => ({
  files: uploads.map((u) => ({
    type: 'file_upload',
    name: u.filename,
    file_upload: { id: u.id },
  })),
})
